mapper.insert:
insert into charge_bill (CHGBILL_CHARGE_MONTH
,RENTAL_PTY_ID
,UNIT_ID
,BLDG_ID
,CHGBILL_AMOUNT
,CHGBILL_DUE_DATE
,CHGBILL_DESC
,CHGBILL_ACC_NUM) VALUES (
to_char(sysdate,'yyyymm') || LPAD(SEQ_CHGBILL_ID.nextval,'4','0')
,#{rentalPtyId}
,#{unitId}
,#{bldgId}
,#{chgbillAmount}
,#{chgbillDueDate}
,#{chgbillDesc}
,#{chgbillAccNum})

